1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getPedidosCozinha, atualizarStatusPedido, getMinhaEmpresa, renovarTokenCozinha } from '../../services/restauranteService';
4	import {
5	  getCozinhaToken, setCozinhaToken, clearCozinhaToken,
6	  getCozinhaMe, getCozinhaPedidos, atualizarStatusCozinhaPortal,
7	} from '../../services/cozinhaPortalService';
8	import { supabase } from '../../lib/supabase';
9	import Icon from '../../components/AppIcon';
10	import { barcodeValue, getPrinterName, setPrinterName } from '../../utils/printComanda';
11	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
12	
13	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
14	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };
15	
16	const STATUS_INFO = {
17	  confirmed: { label: 'Aguardando Preparo', next: 'preparing', nextLabel: 'Iniciar Preparo', nextIcon: 'ChefHat', prev: 'pending', prevLabel: 'Pendente', color: 'border-blue-300 bg-blue-50', badge: 'bg-blue-100 text-blue-800', btnColor: 'bg-orange-500 hover:bg-orange-600' },
18	  preparing: { label: 'Em Preparo', next: 'ready', nextLabel: 'Marcar Pronto', nextIcon: 'Package', prev: 'confirmed', prevLabel: 'Ag. Preparo', color: 'border-orange-300 bg-orange-50', badge: 'bg-orange-100 text-orange-800', btnColor: 'bg-purple-600 hover:bg-purple-700' },
19	};
20	
21	const OrderCard = ({ pedido, onAvancar, onVoltar, atualizando, restauranteNome, highlighted }) => {
22	  const si = STATUS_INFO[pedido.status];
23	  const isAtualizando = atualizando === pedido.id;
24	  const minutos = Math.floor((Date.now() - new Date(pedido.created_at)) / 60000);
25	  const isHighlighted = highlighted === pedido.id;
26	
27	  return (
28	    <div
29	      id={`order-${pedido.id}`}
30	      className={`rounded-2xl border-2 overflow-hidden flex flex-col transition-all duration-300 ${
31	        isHighlighted
32	          ? 'border-yellow-400 bg-yellow-50 shadow-xl shadow-yellow-300/40 scale-[1.02]'
33	          : si?.color ?? 'border-gray-200 bg-white'
34	      }`}
35	    >
36	      {isHighlighted && (
37	        <div className="bg-yellow-400 px-4 py-1.5 flex items-center gap-2">
38	          <Icon name="ScanLine" size={14} className="text-yellow-900" />
39	          <p className="text-xs font-black text-yellow-900 uppercase tracking-wide">Pedido encontrado via leitura</p>
40	        </div>
41	      )}
42	
43	      <div className="px-4 pt-3 pb-2 flex items-start justify-between gap-2">
44	        <div>
45	          <div className="flex items-center gap-2 mb-0.5">
46	            <p className="text-2xl font-black text-[#18181B]">#{pedido.id}</p>
47	            <span className={`text-xs px-2 py-0.5 rounded-full font-bold ${si?.badge}`}>{si?.label}</span>
48	          </div>
49	          {pedido.customers?.name && (
50	            <p className="text-sm font-semibold text-[#27272A]">{pedido.customers.name}</p>
51	          )}
52	          <p className="text-xs text-[#71717A] mt-0.5 flex items-center gap-1">
53	            <Icon name="Clock" size={11} />
54	            {new Date(pedido.created_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
55	            <span className={`ml-1 font-semibold ${minutos > 15 ? 'text-red-500' : minutos > 8 ? 'text-orange-500' : 'text-green-600'}`}>
56	              · {minutos}min
57	            </span>
58	          </p>
59	        </div>
60	        <div className="flex flex-col gap-1.5 flex-shrink-0">
61	          <div className="flex items-center justify-center gap-1 px-2 py-1 bg-[#F4F4F5] rounded-lg">
62	            <Icon name="Barcode" size={11} className="text-[#71717A]" />
63	            <span className="text-[10px] font-mono text-[#71717A]">{barcodeValue(pedido.id)}</span>
64	          </div>
65	        </div>
66	      </div>
67	
68	      <div className="px-4 py-3 bg-white mx-3 rounded-xl mb-3 border border-[#E4E4E7] flex-1">
69	        <div className="space-y-2">
70	          {(pedido.itens ?? []).map((item) => (
71	            <div key={item.id} className="flex items-start gap-2">
72	              <span className="w-7 h-7 bg-[#FF441F] text-white font-black text-sm rounded-lg flex items-center justify-center flex-shrink-0 mt-0.5">
73	                {item.quantity}
74	              </span>
75	              <p className="text-sm font-semibold text-[#18181B] leading-tight">{item.product_name ?? `Produto #${item.product_id}`}</p>
76	            </div>
77	          ))}
78	        </div>
79	        <div className="flex items-center justify-between mt-3 pt-2 border-t border-[#F4F4F5]">
80	          <span className="text-xs text-[#71717A]">{PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method}</span>
81	          <span className="text-sm font-black text-[#FF441F]">{fmt(pedido.total)}</span>
82	        </div>
83	      </div>
84	
85	      <div className="px-3 pb-3 flex gap-2">
86	        <button
87	          disabled={isAtualizando}
88	          onClick={() => onVoltar(pedido.id, si?.prev)}
89	          className="flex items-center justify-center gap-1.5 px-3 py-2.5 bg-white border border-[#E4E4E7] rounded-xl text-xs font-bold text-[#71717A] hover:bg-[#F4F4F5] disabled:opacity-40 transition-colors"
90	        >
91	          <Icon name="ArrowLeft" size={13} />
92	          {si?.prevLabel}
93	        </button>
94	        <button
95	          disabled={isAtualizando}
96	          onClick={() => onAvancar(pedido.id, si?.next)}
97	          className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-white text-sm font-black rounded-xl disabled:opacity-50 transition-colors shadow-md ${si?.btnColor}`}
98	        >
99	          {isAtualizando ? (
100	            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
101	          ) : (
102	            <>
103	              <Icon name={si?.nextIcon ?? 'ArrowRight'} size={15} />
104	              {si?.nextLabel}
105	            </>
106	          )}
107	        </button>
108	      </div>
109	    </div>
110	  );
111	};
112	
113	// Login screen para acesso via token (sem conta de dono)
114	const CozinhaLogin = ({ onLogin }) => {
115	  const [token, setToken] = useState('');
116	  const [erro, setErro] = useState(null);
117	  const [loading, setLoading] = useState(false);
118	
119	  const handleSubmit = async (e) => {
120	    e.preventDefault();
121	    setErro(null);
122	    setLoading(true);
123	    setCozinhaToken(token.trim());
124	    try {
125	      await getCozinhaMe();
126	      onLogin();
127	    } catch {
128	      clearCozinhaToken();
129	      setErro('Link inválido. Solicite um novo link ao restaurante.');
130	    } finally {
131	      setLoading(false);
132	    }
133	  };
134	
135	  return (
136	    <div className="min-h-screen bg-[#1A1A1A] flex items-center justify-center p-4">
137	      <div className="bg-[#232323] rounded-2xl border border-[#2A2A2A] p-6 w-full max-w-sm shadow-2xl">
138	        <div className="text-center mb-6">
139	          <div className="w-14 h-14 bg-orange-500/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
140	            <Icon name="ChefHat" size={28} className="text-orange-400" />
141	          </div>
142	          <h1 className="text-lg font-black text-white">Painel da Cozinha</h1>
143	          <p className="text-sm text-[#71717A] mt-1">Cole o token recebido do restaurante</p>
144	        </div>
145	        <form onSubmit={handleSubmit} className="space-y-3">
146	          <input
147	            value={token}
148	            onChange={(e) => setToken(e.target.value)}
149	            placeholder="Token de acesso..."
150	            required
151	            className="w-full bg-[#1A1A1A] border border-[#3A3A3A] rounded-xl px-3 py-3 text-sm font-mono text-white focus:outline-none focus:border-orange-500"
152	          />
153	          {erro && <p className="text-xs text-red-400">{erro}</p>}
154	          <button type="submit" disabled={loading || !token.trim()}
155	            className="w-full py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 disabled:opacity-50 text-sm">
156	            {loading ? 'Verificando...' : 'Entrar'}
157	          </button>
158	        </form>
159	      </div>
160	    </div>
161	  );
162	};
163	
164	const RestauranteCozinha = () => {
165	  const navigate = useNavigate();
166	
167	  // Detecta modo token sincronamente — antes da primeira renderização
168	  const [modoToken] = useState(() => {
169	    const params = new URLSearchParams(window.location.search);
170	    const urlToken = params.get('cozinha_token');
171	    if (urlToken) {
172	      setCozinhaToken(urlToken);
173	      window.history.replaceState({}, '', '/restaurante/cozinha');
174	    }
175	    return !!getCozinhaToken();
176	  });
177	  const [authed, setAuthed] = useState(() => !!getCozinhaToken());
178	  const [pedidos, setPedidos] = useState([]);
179	  const [restauranteNome, setRestauranteNome] = useState('');
180	  const [restauranteId, setRestauranteId] = useState(null);
181	  const [loading, setLoading] = useState(true);
182	  const [atualizando, setAtualizando] = useState(null);
183	  const [lastUpdate, setLastUpdate] = useState(null);
184	  const [erro, setErro] = useState(null);
185	  const [scanInput, setScanInput] = useState('');
186	  const [highlighted, setHighlighted] = useState(null);
187	  const [scanMsg, setScanMsg] = useState(null);
188	  const [showPrinterSettings, setShowPrinterSettings] = useState(false);
189	  const [printerInput, setPrinterInput] = useState('');
190	  const [printerSaved, setPrinterSaved] = useState(false);
191	  const [copiadoLink, setCopiadoLink] = useState(false);
192	  const [gerandoLink, setGerandoLink] = useState(false);
193	  const scanRef = useRef(null);
194	  const prevOrderIds = useRef(new Set());
195	  const firstLoad = useRef(true);
196	  const tocarSom = useNotificacaoSonora('cozinha');
197	
198	  const copiarLinkCozinha = async () => {
199	    setGerandoLink(true);
200	    try {
201	      const { cozinha_token } = await renovarTokenCozinha();
202	      const base = window.location.origin;
203	      const texto = `${base}/restaurante/cozinha?cozinha_token=${cozinha_token}`;
204	      if (navigator.clipboard && window.isSecureContext) {
205	        await navigator.clipboard.writeText(texto);
206	      } else {
207	        const el = document.createElement('textarea');
208	        el.value = texto; el.style.cssText = 'position:fixed;left:-9999px';
209	        document.body.appendChild(el); el.focus(); el.select();
210	        document.execCommand('copy'); document.body.removeChild(el);
211	      }
212	      setCopiadoLink(true);
213	      setTimeout(() => setCopiadoLink(false), 2500);
214	    } catch (e) {
215	      alert('Erro ao gerar link: ' + e.message);
216	    } finally {
217	      setGerandoLink(false);
218	    }
219	  };
220	
221	  const handleSavePrinter = () => {
222	    setPrinterName(printerInput.trim());
223	    setPrinterSaved(true);
224	    setTimeout(() => setPrinterSaved(false), 2000);
225	  };
226	
227	  const carregar = useCallback(async (currentRestauranteNome, usarToken = false) => {
228	    try {
229	      const data = usarToken ? await getCozinhaPedidos() : await getPedidosCozinha();
230	      const newPedidos = data.pedidos ?? [];
231	
232	      if (!firstLoad.current) {
233	        const novos = newPedidos.filter((p) => !prevOrderIds.current.has(p.id));
234	        if (novos.length > 0) tocarSom();
235	      }
236	
237	      prevOrderIds.current = new Set(newPedidos.map((p) => p.id));
238	      firstLoad.current = false;
239	      setPedidos(newPedidos);
240	      setLastUpdate(new Date());
241	      setErro(null);
242	    } catch (e) {
243	      setErro(e.message);
244	    } finally {
245	      setLoading(false);
246	    }
247	  }, []);
248	
249	  useEffect(() => {
250	    if (modoToken && !authed) return;
251	
252	    let nome = '';
253	
254	    if (modoToken) {
255	      getCozinhaMe()
256	        .then((d) => { nome = d.restaurante?.name ?? ''; setRestauranteNome(nome); setRestauranteId(d.restaurante?.id ?? null); })
257	        .catch(() => {});
258	      carregar(nome, true);
259	      const id = setInterval(() => carregar(nome, true), 30000);
260	      return () => clearInterval(id);
261	    }
262	
263	    getMinhaEmpresa()
264	      .then((d) => {
265	        nome = d.empresa?.name ?? '';
266	        setRestauranteNome(nome);
267	        setRestauranteId(d.empresa?.id ?? null);
268	      })
269	      .catch(() => {});
270	
271	    carregar(nome);
272	    const id = setInterval(() => carregar(nome), 30000);
273	    return () => clearInterval(id);
274	  }, [carregar, modoToken, authed]);
275	
276	  // Realtime: recarrega cozinha quando pedido muda de status
277	  useEffect(() => {
278	    if (!restauranteId) return;
279	    const channel = supabase
280	      .channel(`cozinha-${restauranteId}`)
281	      .on('postgres_changes', {
282	        event: '*',
283	        schema: 'public',
284	        table: 'orders',
285	        filter: `restaurant_id=eq.${restauranteId}`,
286	      }, () => carregar(restauranteNome))
287	      .subscribe();
288	    return () => supabase.removeChannel(channel);
289	  }, [restauranteId, carregar, restauranteNome]);
290	
291	  useEffect(() => {
292	    const saved = getPrinterName();
293	    setPrinterInput(saved);
294	  }, []);
295	
296	  const buscarPorId = useCallback((rawValue) => {
297	    const id = parseInt(rawValue.replace(/\D/g, ''));
298	    if (!id) return;
299	    const found = pedidos.find((p) => p.id === id);
300	    if (found) {
301	      setHighlighted(id);
302	      setScanMsg({ tipo: 'ok', texto: `Pedido #${id} encontrado` });
303	      setTimeout(() => { setHighlighted(null); setScanMsg(null); }, 4000);
304	      setTimeout(() => {
305	        document.getElementById(`order-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
306	      }, 50);
307	    } else {
308	      setScanMsg({ tipo: 'erro', texto: `Pedido #${id} não está na cozinha agora` });
309	      setTimeout(() => setScanMsg(null), 3000);
310	    }
311	    setScanInput('');
312	    scanRef.current?.focus();
313	  }, [pedidos]);
314	
315	  const handleScanKey = (e) => {
316	    if (e.key === 'Enter') { e.preventDefault(); buscarPorId(scanInput); }
317	  };
318	
319	  const handleAvancar = async (pedidoId, novoStatus) => {
320	    setAtualizando(pedidoId);
321	    try {
322	      if (modoToken) {
323	        await atualizarStatusCozinhaPortal(pedidoId, novoStatus);
324	        await carregar(restauranteNome, true);
325	      } else {
326	        await atualizarStatusPedido(pedidoId, novoStatus);
327	        await carregar(restauranteNome);
328	      }
329	    } catch (e) {
330	      alert(e.message);
331	    } finally {
332	      setAtualizando(null);
333	    }
334	  };
335	
336	  const confirmados = pedidos.filter((p) => p.status === 'confirmed');
337	  const preparando = pedidos.filter((p) => p.status === 'preparing');
338	
339	  // Modo token: mostrar login se não autenticado
340	  if (modoToken && !authed) {
341	    return <CozinhaLogin onLogin={() => setAuthed(true)} />;
342	  }
343	
344	  if (loading) return (
345	    <div className="min-h-screen bg-[#1A1A1A] flex items-center justify-center">
346	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
347	    </div>
348	  );
349	
350	  return (
351	    <div className="min-h-screen bg-[#111111]">
352	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
353	        <div className="flex items-center gap-4 mb-3">
354	          {modoToken ? (
355	            <button onClick={() => { clearCozinhaToken(); window.location.reload(); }}
356	              className="p-2 text-[#71717A] hover:text-red-400 rounded-lg hover:bg-[#2A2A2A]" title="Sair">
357	              <Icon name="LogOut" size={18} />
358	            </button>
359	          ) : (
360	            <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
361	              <Icon name="ArrowLeft" size={18} />
362	            </button>
363	          )}
364	          <div className="flex items-center gap-2">
365	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
366	              <Icon name="ChefHat" size={16} className="text-white" />
367	            </div>
368	            <div>
369	              <p className="text-white font-black text-base leading-none">Painel da Cozinha</p>
370	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
371	            </div>
372	          </div>
373	          <div className="ml-auto flex items-center gap-2">
374	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
375	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
376	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
377	            </div>
378	            {/* Botão copiar link — só para o dono, não no modo token */}
379	            {!modoToken && (
380	              <button
381	                onClick={copiarLinkCozinha}
382	                disabled={gerandoLink}
383	                title="Copiar link de acesso para a cozinha"
384	                className={`p-2 rounded-lg transition-colors disabled:opacity-50 ${copiadoLink ? 'text-green-400 bg-green-400/10' : 'text-[#71717A] hover:text-white hover:bg-[#2A2A2A]'}`}
385	              >
386	                <Icon name={gerandoLink ? 'Loader2' : copiadoLink ? 'Check' : 'Link'} size={16}
387	                  className={gerandoLink ? 'animate-spin' : ''} />
388	              </button>
389	            )}
390	            <button onClick={() => { setShowPrinterSettings((v) => !v); setPrinterInput(getPrinterName()); }}
391	              className={`p-2 rounded-lg transition-colors ${showPrinterSettings ? 'text-[#FF441F] bg-[#FF441F]/10' : 'text-[#71717A] hover:text-white hover:bg-[#2A2A2A]'}`}
392	              title="Configurar impressora">
393	              <Icon name="Printer" size={16} />
394	            </button>
395	            <button onClick={() => carregar(restauranteNome)} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
396	              <Icon name="RefreshCw" size={16} />
397	            </button>
398	          </div>
399	        </div>
400	
401	        {/* Printer settings inline bar */}
402	        {showPrinterSettings && (
403	          <div className="mb-3 flex items-center gap-3 bg-[#111111] border border-[#2A2A2A] rounded-xl px-4 py-3">
404	            <Icon name="Printer" size={15} className="text-[#FF441F] flex-shrink-0" />
405	            <div className="flex-1">
406	              <p className="text-xs text-[#71717A] mb-1">Nome da impressora padrão (como aparece no Windows/Mac)</p>
407	              <div className="flex gap-2">
408	                <input
409	                  type="text"
410	                  value={printerInput}
411	                  onChange={(e) => setPrinterInput(e.target.value)}
412	                  onKeyDown={(e) => e.key === 'Enter' && handleSavePrinter()}
413	                  placeholder="Ex: EPSON TM-T20, HP LaserJet..."
414	                  className="flex-1 bg-[#1A1A1A] border border-[#2A2A2A] rounded-lg px-3 py-1.5 text-sm text-white placeholder:text-[#3A3A3A] outline-none focus:border-[#FF441F]"
415	                />
416	                <button onClick={handleSavePrinter}
417	                  className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-colors ${printerSaved ? 'bg-green-600 text-white' : 'bg-[#FF441F] text-white hover:bg-[#E63A19]'}`}>
418	                  {printerSaved ? '✓ Salvo' : 'Salvar'}
419	                </button>
420	                {getPrinterName() && (
421	                  <button onClick={() => { setPrinterName(''); setPrinterInput(''); }}
422	                    className="px-3 py-1.5 text-xs font-bold bg-[#2A2A2A] text-[#71717A] hover:text-white rounded-lg">
423	                    Limpar
424	                  </button>
425	                )}
426	              </div>
427	            </div>
428	          </div>
429	        )}
430	
431	        {/* Scanner / barcode reader input */}
432	        <div className="flex items-center gap-3">
433	          <div className={`flex-1 flex items-center gap-2 px-3 py-2.5 rounded-xl border transition-colors ${
434	            scanMsg?.tipo === 'ok' ? 'border-green-500 bg-green-900/20' :
435	            scanMsg?.tipo === 'erro' ? 'border-red-500 bg-red-900/20' :
436	            'border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]'
437	          }`}>
438	            <Icon name="ScanLine" size={16} className={scanMsg?.tipo === 'ok' ? 'text-green-400' : scanMsg?.tipo === 'erro' ? 'text-red-400' : 'text-[#71717A]'} />
439	            <input
440	              ref={scanRef}
441	              type="text"
442	              value={scanInput}
443	              onChange={(e) => setScanInput(e.target.value)}
444	              onKeyDown={handleScanKey}
445	              placeholder="Aponte o leitor ou digite o nº do pedido..."
446	              className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none font-mono"
447	              autoFocus
448	            />
449	            {scanInput && (
450	              <button onClick={() => buscarPorId(scanInput)}
451	                className="flex-shrink-0 px-3 py-1 bg-[#FF441F] text-white text-xs font-bold rounded-lg hover:bg-[#E63A19]">
452	                Buscar
453	              </button>
454	            )}
455	          </div>
456	          {scanMsg && (
457	            <p className={`text-xs font-semibold flex-shrink-0 ${scanMsg.tipo === 'ok' ? 'text-green-400' : 'text-red-400'}`}>
458	              {scanMsg.texto}
459	            </p>
460	          )}
461	        </div>
462	      </header>
463	
464	      {erro && (
