141	          <Icon name="ArrowLeft" size={20} className="text-gray-600" />
142	        </button>
143	        <h1 className="text-lg font-bold text-gray-900">Pedido #{pedido.id}</h1>
144	      </header>
145	
146	      <main className="p-4 max-w-lg mx-auto space-y-4">
147	        {/* Status atual */}
148	        <div className={`rounded-xl border p-5 text-center ${statusInfo.bg}`}>
