283	            className="flex-1 py-2.5 bg-orange-500 text-white text-sm font-medium rounded-lg hover:bg-orange-600"
284	          >
285	            Meus pedidos
286	          </button>
287	        </div>
288	
289	        <p className="text-center text-xs text-gray-400">Atualização em tempo real</p>
290	      </main>
291	    </div>
